import {TYPES,STEP,END,COST,WORK,MAX_PROJECTS,SLOTS,createRegion,tickRegion,counts,metrics,startBuild} from './region-model.js';
import {createUrbanWorld} from './urban-world.js';
import {createTerritory,tickTerritory,TOWNS,covered,townCapacity} from './territory-model.js';
import {createNarrator} from './narrator.js';
const $=id=>document.getElementById(id),fmt=(n,d=0)=>n.toLocaleString('es-ES',{maximumFractionDigits:d});
let state=createTerritory(),reference=createTerritory(0,false),playing=false,speed=1,motion=0,selected=-1,last=performance.now(),accumulator=0,uiTime=0,world;
const narrator=createNarrator({toggleHost:document.querySelector('.region-top'),onBegin(){playing=false;update();}});
try{world=createUrbanWorld($('r-canvas'),{regional:true});$('r-loading').hidden=true;}catch(e){$('r-loading').textContent='No se pudo iniciar el mundo 3D. Los controles y la comparación siguen disponibles.';console.error(e);}
const labels=[],tabs=[],townLabels=[],townCards=[];let townSelected=-1;
TOWNS.forEach((t,i)=>{for(const overlay of [true,false]){const b=document.createElement('button');b.type='button';b.className=overlay?'region-zone town-zone':'town-card';b.innerHTML='<span>'+t.name+'</span><strong></strong><small></small><i><em></em></i>';b.onclick=()=>selectTown(i);(overlay?$('r-town-labels'):$('r-town-cards')).append(b);(overlay?townLabels:townCards).push(b);}});
const sectors=document.createElement('div');sectors.className='region-sectors';sectors.setAttribute('aria-label','Seleccionar una industria');document.querySelector('.region-chain').after(sectors);
TYPES.forEach((t,i)=>{for(const overlay of [true,false]){const b=document.createElement('button');b.type='button';b.className=overlay?'region-zone':'region-sector';b.innerHTML='<b>'+String(i+1).padStart(2,'0')+'</b><span>'+t.name+'</span><small></small>';b.setAttribute('aria-label','Seleccionar '+t.name);b.addEventListener('click',()=>select(i*SLOTS));(overlay?$('r-labels'):sectors).append(b);(overlay?labels:tabs).push(b);}});
const limits={
  start:['Equilibrio inicial','La región necesita reforzar toda su cadena para seguir creciendo.'],
  power:['Falta potencia eléctrica','La demanda supera la generación. Ampliar energía permite aprovechar mejor las fábricas y las obras.'],
  transport:['Transporte saturado','La red no puede mover todo el flujo potencial. Más capacidad logística permite conectar las ampliaciones.'],
  kits:['Faltan componentes','Las fábricas de robots esperan kits. Reforzar componentes o sus proveedores puede desbloquearlas.'],
  material:['Material para la próxima obra','La construcción y los componentes comparten material. Ampliar el refinado puede liberar recursos para invertir.'],
  land:['El mapa tiene un límite','Todas las parcelas están ocupadas. La flota puede seguir creciendo, pero la capacidad regional ya no se amplía.'],
  machines:['Robots sin un puesto disponible','Hay más robots que puestos en las instalaciones actuales. Las nuevas obras pueden crear capacidad útil.'],
  balanced:['La cadena avanza junta','La próxima ampliación necesita trabajadores, material y tiempo. La producción aumenta cuando la nueva capacidad entra en servicio.']
};
function chart(element,series,maxTime=END){
  const width=320,height=['r-chart','r-rate-chart'].includes(element.id)?130:110,bottom=height-7,peak=Math.max(1,...series.flatMap(s=>s.values.map(p=>p[1]))),left=28,right=316,top=12;
  let svg='';for(let n=0;n<3;n++){const y=top+(bottom-top)*n/2;svg+='<path d="M'+left+' '+y+'H'+right+'" stroke="#718c9e" stroke-opacity=".2"/><text x="0" y="'+(y+3)+'" fill="#91aebe" font-size="9">'+fmt(peak*(1-n/2))+'</text>';}
  series.forEach((s,i)=>{const points=s.values.map(([x,y])=>(left+x/maxTime*(right-left)).toFixed(2)+','+(bottom-y/peak*(bottom-top)).toFixed(2)).join(' ');svg+='<polyline points="'+points+'" fill="none" stroke="'+s.color+'" stroke-width="'+(i?2.5:1.7)+'" '+(i?'':'stroke-dasharray="4 4"')+' stroke-linecap="round" stroke-linejoin="round"/>';});element.innerHTML=svg;
}
function update(){
  const n=counts(state),m=metrics(state),projects=state.sites.filter(p=>p.status==='building'),limit=limits[state.reason];
  $('r-cycle').textContent='CICLO '+String(Math.floor(state.time)).padStart(2,'0');$('r-play-state').textContent=playing?'En marcha':'En pausa';$('r-play').textContent=playing?'Ⅱ Pausar':state.time>=END?'↺ Repetir':'▶ Reproducir';$('r-progress').style.width=state.time/END*100+'%';
  $('r-fleet').textContent=fmt(state.fleet+state.exported);$('r-fleet-note').textContent='24 iniciales + '+fmt(state.built)+' nuevos';$('r-buildings').textContent=n.reduce((a,b)=>a+b,0);$('r-projects').textContent=projects.length+' obras en marcha';$('r-rate').textContent=fmt(state.flow[3],1);$('r-multiple').textContent=fmt(reference.flow[3],1)+' / ciclo sin nuevas instalaciones';
  $('r-working').textContent=fmt(m.working)+' produciendo';$('r-builders').textContent=fmt(m.builders)+' construyendo';$('r-idle').textContent=fmt(m.idle)+' disponibles';$('r-share-label').textContent=Math.round(state.share*100)+' %';
  $('r-gain').textContent=fmt((state.fleet+state.exported)/(reference.fleet+reference.exported),2)+'×';$('r-chart-end').textContent='Ciclo '+Math.floor(state.time)+' / 120';
  chart($('r-chart'),[{values:[[0,24],...reference.urbanHistory.map(p=>[p.time,p.total])],color:'#839eaf'},{values:[[0,24],...state.urbanHistory.map(p=>[p.time,p.total])],color:'#a7e0cf'}]);$('r-chart').setAttribute('aria-label','Flota: '+fmt(state.fleet+state.exported)+'; sin nuevas instalaciones: '+fmt(reference.fleet+reference.exported));chart($('r-rate-chart'),[{values:[[0,0],...reference.urbanHistory.map(h=>[h.time,h.rate])],color:'#839eaf'},{values:[[0,0],...state.urbanHistory.map(h=>[h.time,h.rate])],color:'#a7e0cf'}]);
  $('r-limit').textContent=limit[0];$('r-limit-note').textContent=limit[1];
  for(const [id,ratio] of [['power',m.energyDemand/m.power],['log',m.freight/Math.max(.001,m.transport)]]){$('r-'+id+'-label').textContent=fmt(ratio*100)+' %';$('r-'+id+'-bar').style.width=Math.min(100,ratio*100)+'%';$('r-'+id+'-bar').classList.toggle('over',ratio>1);}
  const event=state.events.at(-1);$('r-event').textContent=state.time>=END?'Fin del escenario. Compara la flota y prueba otra inversión.':event?(event.event==='opened'?'Nueva instalación abierta: ':'Obra iniciada: ')+TYPES[event.type].name+'. '+(event.event==='opened'?'La capacidad ya está disponible.':'El material ya se ha reservado.'):'24 robots. Seis instalaciones. Una nueva escala.';
  TYPES.forEach((t,i)=>{for(const b of [labels[i],tabs[i]]){b.querySelector('small').textContent=n[i]+' / 6 '+(projects.some(p=>p.type===i)?' · obra':'');b.setAttribute('aria-pressed',String(selected>=0&&Math.floor(selected/SLOTS)===i));}});
  $('r-delivery-value').textContent=Math.round(state.delivery*100)+' %';$('r-urban-total').textContent=state.delivered;$('r-in-transit').textContent=state.shipments.length;$('r-depot').textContent=state.depot;$('r-industrial-fleet').textContent=state.fleet;
  state.towns.forEach((t,i)=>{const total=t.tasks.reduce((a,b)=>a+b,0),n=covered(t);for(const b of [townLabels[i],townCards[i]]){b.querySelector('strong').textContent=fmt(n/total*100,1)+' %';b.querySelector('small').textContent=n+' / '+total+' · '+t.reserved+' '+ 'de camino';b.querySelector('em').style.width=n/total*100+'%';b.setAttribute('aria-pressed',String(townSelected===i));}});
  if(townSelected>=0)inspectTown();if(selected>=0)inspect();
}
function inspect(){const p=state.sites[selected],t=TYPES[p.type];$('r-selected-name').textContent=t.name+' · '+String(p.slot+1).padStart(2,'0');$('r-selected-description').textContent=t.description;$('r-selected-state').textContent=p.status==='open'?'INSTALACIÓN OPERATIVA':p.status==='building'?'OBRA · '+fmt(p.progress/WORK*100)+' %':'PARCELA DISPONIBLE';
  const full=state.sites.filter(p=>p.status==='building').length>=MAX_PROJECTS;$('r-build').hidden=p.status!=='empty';$('r-build').disabled=state.material<COST||full||state.time>=END;$('r-build').textContent=full?'Tres obras en marcha':state.material<COST?'Falta material':'Construir aquí · 48';
  const projectOrder=state.sites.filter(site=>site.status==='building').indexOf(p),projectWorkers=Math.max(0,Math.min(4,metrics(state).builders-projectOrder*4));
  $('r-build-note').textContent=p.status==='building'?fmt(projectWorkers)+' robots en esta obra · '+fmt(WORK-p.progress,1)+' unidades de trabajo pendientes.':p.status==='empty'?'Coste: 48 lotes de material. Trabajo: 24 unidades. Asigna robots a obras para avanzar.':'Capacidad instalada. Su producción depende de los trabajadores, la energía y los suministros.';
  $('r-enter').hidden=p.status!=='open';$('r-output').textContent=fmt(state.flow[p.type],1);$('r-site-unit').textContent=t.unit;
  chart($('r-site-chart'),[{values:[[0,0],...reference.history.map(h=>[h.time,h.flow[p.type]])],color:'#839eaf'},{values:[[0,0],...state.history.map(h=>[h.time,h.flow[p.type]])],color:'#a7e0cf'}]);$('r-site-chart').setAttribute('aria-label',t.name+': '+fmt(state.flow[p.type],1)+' '+t.unit);
  $('r-ore').textContent=fmt(state.ore,1);$('r-material').textContent=fmt(state.material,1);$('r-kits').textContent=fmt(state.kits,1);
}
function select(i,narrate=true){if(i<0)return;if(i>=36){selectTown(i-36,narrate);return;}townSelected=-1;$('r-town-inspector').hidden=true;selected=i;$('r-inspector').hidden=false;world?.select(i);update();const p=state.sites[i];if(narrate)narrator.explain('region-'+p.type,p.status==='building'?'region-project':p.status==='open'?'region-operation':null);if(narrate&&matchMedia('(max-width:760px)').matches)$('r-inspector').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function step(){tickTerritory(state);tickTerritory(reference);if(state.time>=END)playing=false;}
function reset(){narrator.stop();state=createTerritory(Number($('r-share').value)/100,$('r-auto').checked,Number($('r-delivery').value)/100);reference=createTerritory(0,false,Number($('r-delivery').value)/100);townSelected=-1;$('r-town-inspector').hidden=true;playing=false;motion=0;accumulator=0;selected=-1;$('r-inspector').hidden=true;world?.select(-1,false);world?.fit();update();}
document.addEventListener('click',e=>{if(e.target.closest('#r-play,#r-jump,#r-reset,#r-build,#r-close,#r-help,#r-assumptions'))narrator.stop();},true);
$('r-play').onclick=()=>{if(state.time>=END)reset();playing=!playing;last=performance.now();update();};$('r-speed').onchange=e=>speed=Number(e.target.value);$('r-reset').onclick=reset;
$('r-jump').onclick=()=>{playing=false;for(let i=0;i<10/STEP&&state.time<END;i++)step();update();};$('r-share').oninput=e=>{narrator.stop();state.share=Number(e.target.value)/100;update();};$('r-auto').onchange=e=>{narrator.stop();state.auto=e.target.checked;update();};
$('r-build').onclick=()=>{if(startBuild(state,selected)){playing=true;last=performance.now();update();}};$('r-close').onclick=()=>{selected=-1;$('r-inspector').hidden=true;world?.select(-1,false);world?.fit();update();};$('r-enter').onclick=()=>location.href='./district.html';
$('r-delivery').oninput=e=>{narrator.stop();state.delivery=reference.delivery=Number(e.target.value)/100;update();};
$('r-plus').onclick=()=>world?.zoomBy(1.25);$('r-minus').onclick=()=>world?.zoomBy(.8);$('r-fit').onclick=()=>world?.fit();
function help(){playing=false;update();$('r-about').showModal();}$('r-help').onclick=help;$('r-assumptions').onclick=help;$('r-close-help').onclick=()=>$('r-about').close();$('r-explain').onclick=()=>{$('r-about').close();narrator.explain('region-overview');};
const surface=$('r-canvas'),pointers=new Map();let moved=false,start=null,pinch=0;
surface.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});surface.setPointerCapture(e.pointerId);if(pointers.size===1){start={x:e.clientX,y:e.clientY};moved=false;}else{moved=true;const [a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y);}});
surface.addEventListener('pointermove',e=>{const before=pointers.get(e.pointerId);if(!before)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinch>0)world?.zoomBy(d/pinch);pinch=d;moved=true;}else{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>6)moved=true;if(moved)world?.pan(e.clientX-before.x,e.clientY-before.y);}});
surface.addEventListener('pointerup',e=>{if(!moved&&pointers.size===1)select(world?.pick(e.clientX,e.clientY)??-1);pointers.delete(e.pointerId);pinch=0;});surface.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);moved=true;pinch=0;});surface.addEventListener('wheel',e=>{e.preventDefault();world?.zoomBy(Math.exp(-e.deltaY*.001));},{passive:false});
document.addEventListener('visibilitychange',()=>last=performance.now());update();
function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(!document.hidden){if(playing){accumulator+=dt*speed;motion+=dt*Math.min(speed,2);while(accumulator>=STEP&&state.time<END){step();accumulator-=STEP;}}uiTime+=dt;if(uiTime>.25){update();uiTime=0;}const scale=world?.render(state,motion)??1;$('r-scale').textContent=scale===1?'Cada figura representa un robot':'Figuras urbanas: hasta '+scale+' tareas · vehículos: entregas agrupadas';labels.forEach((b,i)=>{if(!world){b.hidden=true;return;}const p=world.project(i);b.style.left=p.x+'px';b.style.top=p.y+'px';b.hidden=p.x<25||p.x>surface.clientWidth-25||p.y<65||p.y>surface.clientHeight-85;});townLabels.forEach((b,i)=>{if(!world){b.hidden=true;return;}const p=world.projectTown(i);b.style.left=p.x+'px';b.style.top=p.y+'px';b.hidden=p.x<30||p.x>surface.clientWidth-30||p.y<65||p.y>surface.clientHeight-85;});}requestAnimationFrame(frame);}requestAnimationFrame(frame);

document.addEventListener('narration-focus',e=>{if(/^region-\d+$/.test(e.detail))select(Number(e.detail.split('-')[1])*SLOTS,false);});

function selectTown(i,narrate=true){selected=-1;townSelected=i;$('r-inspector').hidden=true;$('r-town-inspector').hidden=false;world?.select(36+i);update();if(narrate)narrator.explain('region-city-'+i);}
function inspectTown(){const i=townSelected,t=state.towns[i],n=covered(t),total=t.tasks.reduce((a,b)=>a+b,0);$('r-town-name').textContent=TOWNS[i].name;$('r-town-human').textContent=total-n;$('r-town-robot').textContent=n;$('r-town-travel').textContent=t.travel+' ciclos de traslado · '+t.reserved+' robots de camino';chart($('r-town-chart'),[{values:[[0,0],...reference.urbanHistory.map(h=>[h.time,h.covered[i]])],color:'#839eaf'},{values:[[0,0],...state.urbanHistory.map(h=>[h.time,h.covered[i]])],color:'#70e1c6'}]);}
document.addEventListener('narration-focus',e=>{if(/^region-city-\d+$/.test(e.detail))selectTown(Number(e.detail.split('-')[2]),false);});
